use std::num::ParseIntError;
use std::fmt;

#[derive(PartialEq, Debug)]
pub struct StData {
    size: i32,
    data: Vec<[u8; 3]>,
}

#[derive(Debug)]
pub enum FromStringError {
    ParseSizeError(ParseIntError),
    ParseColError(ParseIntError),
    NoEnd,
}

impl fmt::Display for FromStringError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            FromStringError::ParseSizeError(e) => write!(f, "unable to parse size: {}", e),
            FromStringError::ParseColError(e) => write!(f, "unable to parse colour data: {}", e),
            FromStringError::NoEnd => write!(f, "no endendend given"),
        }
    }
}

impl StData {
    pub fn len(&self) -> usize {
        self.data.len()
    }
    pub fn width(&self) -> usize {
        self.size as usize
    }
    pub fn height(&self) -> usize {
        (self.len() as f32 / self.width() as f32).ceil() as usize
    }
    pub fn to_string(&self) -> String {
        let mut converted = format!("{{{}}}", self.size);
        for d in &self.data {
            if d[0].to_string().len() == 1 {
                converted = format!("{converted}00");
            } else if d[0].to_string().len() == 2 {
                converted = format!("{converted}0");
            }
            if d[1].to_string().len() == 1 {
                converted = format!("{converted}00");
            } else if d[1].to_string().len() == 2 {
                converted = format!("{converted}0");
            }
            if d[2].to_string().len() == 1 {
                converted = format!("{converted}00");
            } else if d[2].to_string().len() == 2 {
                converted = format!("{converted}0");
            }
            converted = format!("{converted}{}{}{}", d[0], d[1], d[2]);
        }
        converted = converted.replace("255255255", "w").replace("255000000", "r").replace("000255000", "g").replace("000000255", "b").replace("000255255", "c").replace("255255000", "y").replace("255000255", "p").replace("000000000", "k");
        format!("{converted}endendend")
    }
    pub fn from_string(arg: String) -> Result<StData, FromStringError> {
        let mut contents = arg.clone();
        contents = contents.replace("w", "255255255");
        contents = contents.replace("r", "255000000");
        contents = contents.replace("g", "000255000");
        contents = contents.replace("b", "000000255");
        contents = contents.replace("c", "000255255");
        contents = contents.replace("y", "255255000");
        contents = contents.replace("p", "255000255");
        contents = contents.replace("k", "000000000");
        let mut stdata_size: i32 = 0;
        let mut stdata_data: Vec<[u8; 3]> = vec![];
        let mut in_size = false;
        let mut data = String::new();
        for c in contents.chars().collect::<Vec<char>>() {
            match c {
                '{' => in_size = true,
                '}' => {
                    if in_size {
                        in_size = false;
                        let stdata_size_raw = data.parse();
                        match stdata_size_raw {
                            Ok(n) => stdata_size = n,
                            Err(e) => return Err(FromStringError::ParseSizeError(e)),
                        }
                        data = String::new();
                    }
                },
                _ => data = format!("{data}{c}"),
            }
            if data.len() > 8 {
                if data == "endendend".to_string() {
                    return Ok(StData { size: stdata_size, data: stdata_data });
                }
                let (redstr, nonred) = data.split_at(3);
                let (greenstr, bluestr) = nonred.split_at(3);
                let red_result = redstr.parse();
                let green_result = greenstr.parse();
                let blue_result = bluestr.parse();
                let red: u8;
                let green: u8;
                let blue: u8;
                match red_result {
                    Ok(n) => red = n,
                    Err(e) => return Err(FromStringError::ParseColError(e)),
                }
                match green_result {
                    Ok(n) => green = n,
                    Err(e) => return Err(FromStringError::ParseColError(e)),
                }
                match blue_result {
                    Ok(n) => blue = n,
                    Err(e) => return Err(FromStringError::ParseColError(e)),
                }
                stdata_data.push([red, green, blue]);
                data = String::new();
            }
        }
        Err(FromStringError::NoEnd)
    }
    pub fn get_pos(&self, x: usize, y: usize) -> [u8; 3] {
        let w = self.width();
        self.data[x + y * w]
    }
    pub fn set_pos(&mut self, x: usize, y: usize, col: [u8; 3]) {
        let w = self.width();
        self.data[x + y * w] = col;
    }
    pub fn data(&self) -> Vec<[u8; 3]> {
        self.data.clone()
    }
}

